import br.com.pelotavision.*;import org.opencv.core.*;import org.opencv.imgproc.Imgproc;import org.opencv.imgcodecs.Imgcodecs;import java.nio.file.*;import java.io.*;import java.util.*;
public class EllipseCheck {
 static void require(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static double angular(double a,double b){double d=Math.abs(a-b)%180;return Math.min(d,180-d);}
 public static void main(String[] args)throws Exception{
  nu.pattern.OpenCV.loadLocally();Core.setNumThreads(2);int cases=0;double maxRatio=0,maxAxis=0;
  for(double ratio:new double[]{1,.8,.6,.5})for(double angle:new double[]{0,35,80})for(boolean dark:new boolean[]{false,true}){
   double a=70,b=a*ratio,r=Math.sqrt(a*b);Mat gray=new Mat(280,400,CvType.CV_8UC1,new Scalar(dark?210:30));Imgproc.ellipse(gray,new Point(200,140),new Size(a,b),angle,0,360,new Scalar(dark?45:195),-1,Imgproc.LINE_AA,0);
   PelletDetector.Detection seed=new PelletDetector.Detection(203,138,r,Math.PI*r*r,1,false,false);PelletDetector.Result fitted=new EllipseFitter().refine(gray,new PelletDetector.Result(Arrays.asList(seed),400,280,1,0,false));PelletDetector.Detection d=fitted.circles.get(0);
   require(d.ellipseFitted,"Fit failed ratio="+ratio+" angle="+angle+" dark="+dark);double re=Math.abs(d.aspectRatio()-ratio);maxRatio=Math.max(maxRatio,re);maxAxis=Math.max(maxAxis,Math.max(Math.abs(d.semiMajor-a),Math.abs(d.semiMinor-b)));
   require(re<.045&&Math.abs(d.semiMajor-a)<4&&Math.abs(d.semiMinor-b)<4,"Incorrect axes "+d.semiMajor+","+d.semiMinor);require(Math.hypot(d.x-200,d.y-140)<3,"Center drift");if(ratio<.95)require(angular(d.angleDeg,angle)<4,"Angle convention");require(Math.abs(d.area-Math.PI*d.semiMajor*d.semiMinor)<1e-8,"Area");require(Math.abs(d.radius*d.radius-d.semiMajor*d.semiMinor)<1e-8,"Equivalent diameter");cases++;gray.release();
  }
  Mat blank=new Mat(240,320,CvType.CV_8UC1,new Scalar(100));PelletDetector.Detection seed=new PelletDetector.Detection(150,100,40,Math.PI*1600,1,false,false);PelletDetector.Result unknown=new EllipseFitter().refine(blank,new PelletDetector.Result(Arrays.asList(seed),320,240,1,0,false));require(!unknown.circles.get(0).ellipseFitted&&ShapeStatistics.of(unknown).included==0&&Double.isNaN(ShapeStatistics.of(unknown).mean),"Uniform background fabricated sphericity");blank.release();
  Mat isolated=new Mat(400,640,CvType.CV_8UC1,new Scalar(220));Imgproc.ellipse(isolated,new Point(310,190),new Size(80,40),35,0,360,new Scalar(50),-1);PelletDetector.Result found=new AdaptivePelletDetector().detect(isolated,PelletDetector.Parameters.automatic(),800,12);PelletDetector.Result refined=new EllipseFitter().refine(isolated,found);require(refined.circles.size()==1&&refined.circles.get(0).ellipseFitted,"Isolated elongated pellet lost");require(Math.abs(refined.circles.get(0).aspectRatio()-.5)<.05,"Isolated aspect ratio");isolated.release();
  System.out.println("PASS analytic ellipses="+cases+" max_ratio_error="+maxRatio+" max_semi_axis_error_px="+maxAxis+"; uniform region excluded; isolated elongated pellet found");
  Path repo=Path.of(args[0]),out=repo.resolve("verification/ellipse-0.6.0");Files.createDirectories(out);CrackModel model;try(InputStream in=Files.newInputStream(repo.resolve("app/src/main/assets/crack_forest.pvrf"))){model=new CrackModel(in);}double scoreError=0;
  for(String scene:new String[]{"brown40","gray42","gray20","dense","cluster","spaced","paired40"}){
   Mat gray=Imgcodecs.imread(repo.resolve("ml_training/data/"+scene+".png").toString(),0);PelletDetector.Result old=new AdaptivePelletDetector().detect(gray,PelletDetector.Parameters.automatic(),1024,12),result=new EllipseFitter().refine(gray,old);CrackAnalysis cracks=new CrackDetector(model).detect(gray,result,50),before=new CrackDetector(model).detect(gray,old,50);ShapeStatistics stats=ShapeStatistics.of(result);
   require(old.circles.size()==result.circles.size(),"Ellipse fitting changed object identity/count");StringBuilder json=new StringBuilder("{\"scene\":\""+scene+"\",\"width\":"+gray.cols()+",\"height\":"+gray.rows()+",\"method\":\""+result.method+"\",\"mean\":"+(Double.isFinite(stats.mean)?stats.mean:"null")+",\"included\":"+stats.included+",\"excluded\":"+stats.excluded+",\"detections\":[");
   for(int i=0;i<result.circles.size();i++){
    PelletDetector.Detection d=result.circles.get(i);CrackAnalysis.Entry e=cracks.entries.get(i);scoreError=Math.max(scoreError,Math.abs(e.modelScore-before.entries.get(i).modelScore));
    if(i>0)json.append(',');json.append(String.format(Locale.ROOT,"{\"id\":%d,\"x\":%.9f,\"y\":%.9f,\"radius\":%.9f,\"area\":%.9f,\"roundness\":%.9f,\"semi_major\":%.9f,\"semi_minor\":%.9f,\"angle\":%.9f,\"fitted\":%s,\"support\":%s,\"rms\":%s,\"partial\":%s,\"review\":%s,\"crack_x\":%.9f,\"crack_y\":%.9f,\"crack_radius\":%.9f,\"crack_review\":%s,\"score\":%.12f,\"status\":\"%s\",\"runs\":[",i+1,d.x,d.y,d.radius,d.area,d.roundness,d.semiMajor,d.semiMinor,d.angleDeg,d.ellipseFitted,Double.isFinite(d.fitSupport)?Double.toString(d.fitSupport):"null",Double.isFinite(d.fitRms)?Double.toString(d.fitRms):"null",d.partial,d.needsReview,d.crackX,d.crackY,d.crackRadius,d.crackNeedsReview,e.modelScore,e.status.name()));float[] runs=e.markedRuns();for(int j=0;j<runs.length;j++){if(j>0)json.append(',');json.append(runs[j]);}json.append("]}");
   }json.append("]}");Files.writeString(out.resolve(scene+"_analysis.json"),json.toString());System.out.printf(Locale.ROOT,"%s: detected=%d mean=%.6f included=%d excluded=%d duration=%dms%n",scene,result.circles.size(),stats.mean,stats.included,stats.excluded,result.durationMs);gray.release();
  }
  require(scoreError==0,"RF crop/score changed");System.out.println("PASS RF score parity before/after ellipse refinement, max error="+scoreError);
 }
}
